export const DEFAULT_PULL_TTL_MINUTES = 60;
export function pullTtlMs(env = process.env, ttlMinutes) {
  const raw = ttlMinutes !== undefined && ttlMinutes !== null ? ttlMinutes : env.VAULT_PULL_TTL_MINUTES;
  const n = raw === undefined || raw === '' ? DEFAULT_PULL_TTL_MINUTES : Number(raw);
  if (!Number.isFinite(n) || n <= 0) throw new VaultSyncError(EXIT.error, '--ttl-minutes / VAULT_PULL_TTL_MINUTES must be a positive number');
  return Math.min(n * 60 * 1000, STAMP_MAX_TTL_MS);
}

/** Overwrite a file with zeros, flush, then delete it. Best effort on the overwrite, always deletes. */
export function shredFile(abs) {
  try {
    const st = fs.statSync(abs);
    if (st.isFile()) {
      const fd = fs.openSync(abs, 'r+');
      try { fs.writeSync(fd, Buffer.alloc(st.size), 0, st.size, 0); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
    }
  } catch { /* fall through to delete */ }
  fs.rmSync(abs, { force: true });
}

